import React, { useEffect, useRef, useState } from 'react';
import { Button, Table, Form, Spinner, Card } from 'react-bootstrap';
import FormLayout from '../../utils/formLayout';
import { staffFilterFormContainer } from './formFieldData';
// import Table from '../../components/Table';
import { findArrObj, numberWithCommas, showMessage } from '../../utils/AllFunction';
import { usePageTitle, useRedux } from '../../hooks';
import { NotificationContainer } from 'react-notifications';
import {
    createStaffSalaryRequest,
    getStaffSalaryRequest,
    resetCreateStaffSalary,
    resetGetStaffSalary,
} from '../../redux/staff-salary/actions';
import {
    getBranchRequest,
    getDepartmentRequest,
    resetGetBranch,
    resetGetDepartment,
} from '../../redux/actions';
import moment from 'moment';
import _ from 'lodash';
import noProfile from '../../assets/images/noprofile_images.jpg';
import { baseURL } from '../../api/ApiConfig';
import { useNavigate } from 'react-router-dom';


function Index() {

    usePageTitle({
        title: 'Salary',
        breadCrumbItems: [
            {
                path: '/salary/staff-salary',
                label: 'Salary',
            },
            {
                path: '/salary/staff-salary',
                label: 'Staff Salary',
                active: true,
            },
        ],
    });

    const { dispatch, appSelector } = useRedux();
    const loginInfo = localStorage.getItem('loginInfo');
    const localData = JSON.parse(loginInfo);
    const pageAccessData = findArrObj(localData?.[0]?.pagePermission, 'label', 'Staff Salary');
    const accessIds = (pageAccessData?.[0]?.access || '').split(',').map((id) => id.trim()); // for access create and update and delete actions ['1', '2', '3', '4', '5', '6']
    const branchIdforRole = localData?.[0]?.branchId; // for branch list can only show
    const roleIdforRole = localData?.[0]?.roleId; // for role Permission (1.superadmin)

    const navigate = useNavigate();

    const {
        getStaffSalarySuccess,
        getStaffSalaryList,
        getStaffSalaryFailure,
        createStaffSalarySuccess,
        createStaffSalaryFailure,
        createStaffSalaryData,
        errorMessage,

        getBranchSuccess,
        getBranchList,
        getBranchFailure,

        getDepartmentSuccess,
        getDepartmentList,
        getDepartmentFailure,

    } = appSelector((state) => ({
        getBranchSuccess: state.branchReducer.getBranchSuccess,
        getBranchList: state.branchReducer.getBranchList,
        getBranchFailure: state.branchReducer.getBranchFailure,

        getDepartmentSuccess: state.departmentReducer.getDepartmentSuccess,
        getDepartmentList: state.departmentReducer.getDepartmentList,
        getDepartmentFailure: state.departmentReducer.getDepartmentFailure,

        getStaffSalarySuccess: state.staffsalaryReducer.getStaffSalarySuccess,
        getStaffSalaryList: state.staffsalaryReducer.getStaffSalaryList,
        getStaffSalaryFailure: state.staffsalaryReducer.getStaffSalaryFailure,


        createStaffSalarySuccess: state.staffsalaryReducer.createStaffSalarySuccess,
        createStaffSalaryData: state.staffsalaryReducer.createStaffSalaryData,
        createStaffSalaryFailure: state.staffsalaryReducer.createStaffSalaryFailure,

        errorMessage: state.staffsalaryReducer.errorMessage,
    }));

    const [state, setState] = useState({
        maximumDate: moment().format('YYYY-MM'),
        departmentId: 0,
        branchId: roleIdforRole != 1 ? branchIdforRole : 0,
        filterSalaryMonth: moment().format('YYYY-MM'),
    });

    const [optionListState, setOptionListState] = useState({
        departmentList: [
            {
                departmentId: 0,
                departmentName: 'All',
            },
        ],
        branchList: [
            {
                branchId: 0,
                branchName: 'All',
            },
        ],
    });
    const [formContain, setFormContain] = useState(staffFilterFormContainer);
    const [parentList, setParentList] = useState([]);
    const [isLoading, setIsLoading] = useState(false);

    useEffect(() => {
        setIsLoading(true);
        let searchReq = {
            salaryDate: `${state.filterSalaryMonth}-01`,
        };
        if (roleIdforRole != 1) {
            searchReq.branchId = branchIdforRole;
        }
        dispatch(getStaffSalaryRequest(searchReq));
        dispatch(getBranchRequest());
        dispatch(getDepartmentRequest());
    }, []);

    useEffect(() => {
        if (roleIdforRole != 1) {
            let arr = staffFilterFormContainer;
            const updatedFormFields = _.filter(
                staffFilterFormContainer[0].formFields,
                (field) => field.name !== 'branchId'
            );
            arr[0].formFields = updatedFormFields;
            setFormContain(arr);
        }
    }, [staffFilterFormContainer, roleIdforRole]);

    useEffect(() => {
        if (getBranchSuccess) {
            setIsLoading(false);
            setOptionListState({
                ...optionListState,
                branchList: [...optionListState.branchList, ...getBranchList],
            });
            dispatch(resetGetBranch());
        } else if (getBranchFailure) {
            setIsLoading(false);
            setOptionListState({
                ...optionListState,
                branchList: [],
            });
            dispatch(resetGetBranch());
        }
    }, [getBranchSuccess, getBranchFailure]);

    useEffect(() => {
        if (getDepartmentSuccess) {
            setIsLoading(false);
            setOptionListState({
                ...optionListState,
                departmentList: [...optionListState.departmentList, ...getDepartmentList],
            });
            dispatch(resetGetDepartment());
        } else if (getDepartmentFailure) {
            setIsLoading(false);
            setOptionListState({
                ...optionListState,
                departmentList: [],
            });
            dispatch(resetGetDepartment());
        }
    }, [getDepartmentSuccess, getDepartmentFailure]);

    useEffect(() => {
        if (getStaffSalarySuccess) {
            setIsLoading(false);
            const salaryList = (getStaffSalaryList || []).map((item) => ({
                ...item,
                monthlySalary: parseFloat(item.monthlySalary).toFixed(2),
                isChecked: true,
                salaryDate: moment().format('YYYY-MM-DD'),
            }));
            setParentList(salaryList);
            dispatch(resetGetStaffSalary());
        } else if (getStaffSalaryFailure) {
            setIsLoading(false);
            dispatch(resetGetStaffSalary());
        }
    }, [getStaffSalarySuccess, getStaffSalaryFailure]);

    useEffect(() => {
        if (createStaffSalarySuccess) {
            let searchReq = {
                salaryDate: `${state.filterSalaryMonth}-01`,
            };
            if (roleIdforRole != 1) {
                searchReq.branchId = branchIdforRole;
            }
            dispatch(getStaffSalaryRequest(searchReq));
            showMessage('success', 'Created Successfully');
            setIsLoading(true);
            dispatch(resetCreateStaffSalary());
        } else if (createStaffSalaryFailure) {
            showMessage('warning', errorMessage);
            dispatch(resetCreateStaffSalary());
        }
    }, [createStaffSalarySuccess, createStaffSalaryFailure]);

    useEffect(() => {
        const staffReq = {
            branchId: state.branchId,
            departmentId: state.departmentId,
            salaryDate: `${state.filterSalaryMonth}-01`,
        };
        state.departmentId <= 0 && delete staffReq.departmentId;
        state.branchId <= 0 && delete staffReq.branchId;
        dispatch(getStaffSalaryRequest(staffReq));
    }, [state.departmentId, state.branchId, state.filterSalaryMonth]);

    const onFormSubmit = async () => {

        const filterCheckedSalary = parentList.filter((val) => val.isChecked === true);

        if (filterCheckedSalary.length === 0) {
            showMessage('error', 'Please select at least one staff member.');
            return;
        }

        const strigifyDeductionDetails = filterCheckedSalary.map(item => ({
            salaryDate: moment().format('YYYY-MM-DD'),
            salariedMonth: moment(state?.filterSalaryMonth).format('MMMM'),
            staffId: item.staffId,
            deductionDetails: JSON.stringify(item.deductionDetails),
            attendanceBasedSalary: JSON.stringify({
                presentDaySalary: item.presentDaySalary,
                absentDaySalary: item.absentDaySalary,
                halfDaySalary: item.halfDaySalary,
                notAttendanceSalary: item.notAttendanceSalary,
                presentAndHalfDaySalary: item.presentAndHalfDaySalary,
                totalHolidayAndSunday: item.totalHolidayAndSunday,
            }),
            attendanceList: JSON.stringify({
                totalMonthDays: item.totalMonthDays,
                totalOfficeDays: item.totalOfficeDays,
                holidays: item.holidays,
                presentPlusHalfdays: item.presentPlusHalfdays,
                presentDays: item.presentDays,
                absentDays: item.absentDays,
                halfDays: item.halfDays,
                attendanceNotEntryCount: item.attendanceNotEntryCount,
            }),
            salaryDetails: JSON.stringify({
                pfRequired: item.pfRequired,
                esiRequired: item.esiRequired,
                monthlySalary: item.monthlySalary,
                netPayableSalary: item.netPayableSalary,
            })
        }))
        const submitRequest = {
            staffSalaryList: strigifyDeductionDetails || []
        };

        dispatch(createStaffSalaryRequest(submitRequest));
    };

    const handleDate = (event, formName) => {
        setState({
            ...state,
            [formName]: event.target.value,
        });
        const filterDepartment = {
            filterSalaryMonth: event.target.value,
            branchId: branchIdforRole,
        };
        dispatch(getStaffSalaryRequest(filterDepartment));
    };

    const handleDepartment = (option, formName, uniqueKey, displayKey) => {
        const filterDepartment = {
            departmentId: option[uniqueKey] || '',
            branchId: state?.branchId || '',
            salaryDate: `${state.filterSalaryMonth}-01`,
        };
        dispatch(getStaffSalaryRequest(filterDepartment));
        setIsLoading(true);
        setState({
            ...state,
            [formName]: option[uniqueKey],
        });
    };

    const handleBranch = (option, formName, uniqueKey, displayKey) => {
        const filterBranch = {
            branchId: option[uniqueKey] || '',
            departmentId: state?.departmentId || '',
            salaryDate: `${state.filterSalaryMonth}-01`,
        };
        dispatch(getStaffSalaryRequest(filterBranch));
        setIsLoading(true);
        setState({
            ...state,
            [formName]: option[uniqueKey],
        });
    };


    // Select Table Rows
    const onHandleAllRows = (value, formName) => {
        setParentList((prev) => {
            const arr = [...prev];
            return arr.map((item) => ({
                ...item,
                [formName]: value,
            }));
        });
    };

    const onHandleEachRow = (value, index, formName) => {
        setParentList((prev) => {
            const arr = [...prev];
            arr[index] = { ...arr[index] };
            arr[index][formName] = value || 0;
            return arr;
        });
    };

    // Allowance Calculation
    const handleAllowanceChange = (personIndex, allowanceKey, field, newValue) => {
        setParentList((prevList) => {
            const updatedList = [...prevList];
            const person = { ...updatedList[personIndex] };

            const allowanceArray = [...person.deductionDetails.allowance];
            const allowanceIndex = allowanceArray.findIndex(item => Object.keys(item)[0] === allowanceKey);
            if (allowanceIndex === -1) return prevList;

            const allowanceItem = { ...allowanceArray[allowanceIndex] };
            const key = Object.keys(allowanceItem)[0];
            const value = { ...allowanceItem[key] };

            value[field] = newValue;

            const perDaySalary = parseFloat(person.monthlySalary) / person.totalMonthDays;
            const earned = Math.round(perDaySalary * (Number(person.presentPlusHalfdays) + Number(person.totalHolidayAndSunday)));
            const totalDeduction = person.deductionDetails?.totalDeduction || 0;

            const isPercentage = Number(value.isPercentage) === 1;
            const newAmount = isPercentage
                ? Math.round((parseFloat(value.deductionValue || 0) / 100) * earned)
                : Number(value.deductionValue);

            const isIncrement = Number(value.isIncrement) === 1;

            // Preview array with updated deductionAmount
            const tempArray = [...allowanceArray];
            tempArray[allowanceIndex] = { [key]: { ...value, deductionAmount: newAmount } };

            // Get total of all increment (isIncluding === 1)
            const incrementTotal = tempArray.reduce((acc, curr) => {
                const v = Object.values(curr)[0];
                return Number(v.isIncrement) === 1 ? acc + Number(v.deductionAmount || 0) : acc;
            }, 0);

            const includingTotal = tempArray.reduce((acc, curr) => {
                const v = Object.values(curr)[0];
                return Number(v.isIncrement) === 0 ? acc + Number(v.deductionAmount || 0) : acc;
            }, 0);

            // Get total of all allowances (for display only)
            const allTotal = tempArray.reduce((acc, curr) => {
                const v = Object.values(curr)[0];
                return acc + Number(v.deductionAmount || 0);
            }, 0);

            const newNetPayable = Math.round(earned + incrementTotal - totalDeduction);

            if (!isIncrement) {
                const cap = Math.round(earned);
                const totalAllowance = tempArray.reduce((acc, curr) => {
                    const v = Object.values(curr)[0];
                    return Number(v.isIncrement) === 0 ? acc + Number(v.deductionAmount || 0) : acc;
                }, 0);

                if (totalAllowance > cap) {
                    showMessage(
                        'error',
                        `Including allowance too high.\nMax Allowed: ₹${cap}  |  Tried: ₹${totalAllowance}`
                    );
                    return prevList;
                }

                if (newNetPayable < 0) {
                    showMessage(
                        'error',
                        `Net Payable cannot be negative.\nEarned: ₹${earned} | Deductions: ₹${totalDeduction}\nAllowance (increment only): ₹${incrementTotal}`
                    );
                    return prevList;
                }
            }

            allowanceItem[key] = { ...value, deductionAmount: newAmount };
            allowanceArray[allowanceIndex] = allowanceItem;

            person.deductionDetails.allowance = allowanceArray;
            person.deductionDetails.totalAllowance = allTotal;
            person.netPayableSalary = newNetPayable;
            person.deductionDetails.totalIncrementAllowance = incrementTotal;
            person.deductionDetails.totalIncludingAllowance = allTotal;


            updatedList[personIndex] = person;
            return updatedList;
        });
    };

    // Deduction Calculation
    const handleDeductionChange = (personIndex, deductionIndex, field, newValue) => {
        setParentList((prevList) => {
            const updatedList = [...prevList];
            const person = { ...updatedList[personIndex] };

            const deductionArray = [...person.deductionDetails.deduction];
            const deductionItem = { ...deductionArray[deductionIndex] };
            const key = Object.keys(deductionItem)[0];
            const value = { ...deductionItem[key] };

            value[field] = newValue;

            const perDaySalary = person.monthlySalary / person.totalMonthDays;
            const earnedAmount = Math.round(perDaySalary * (Number(person.presentPlusHalfdays) + Number(person.totalHolidayAndSunday)));

            const isPercentage = Number(value.isPercentage) === 1;
            const newAmount = isPercentage
                ? Math.round((parseFloat(value.deductionValue || 0) / 100) * earnedAmount)
                : Number(value.deductionValue);

            const tempArray = [...deductionArray];
            tempArray[deductionIndex] = { [key]: { ...value, deductionAmount: newAmount } };

            const newTotalDeduction = tempArray.reduce((acc, curr) => {
                const val = Object.values(curr)[0];
                return acc + Number(val.deductionAmount || 0);
            }, 0);

            const incrementTotal = person.deductionDetails?.totalIncrementAllowance || 0;
            const prevNetPayable = person.netPayableSalary || 0;

            const cap = prevNetPayable + incrementTotal;

            if (newTotalDeduction > cap) {
                showMessage(
                    'error',
                    `Deduction too high.\nMax allowed: ₹${cap}  |  Tried: ₹${newTotalDeduction}`
                );
                return prevList;
            }

            const newNetPayable = Math.round(earnedAmount + incrementTotal - newTotalDeduction);

            if (newNetPayable < 0) {
                showMessage(
                    'error',
                    `Net Payable cannot be negative.
Earned: ₹${earnedAmount} | Increment: ₹${incrementTotal} | Tried Deduction: ₹${newTotalDeduction}`
                );
                return prevList;
            }

            deductionItem[key] = { ...value, deductionAmount: newAmount };
            deductionArray[deductionIndex] = deductionItem;

            person.deductionDetails.deduction = deductionArray;
            person.deductionDetails.totalDeduction = newTotalDeduction;
            person.netPayableSalary = newNetPayable;

            updatedList[personIndex] = person;
            return updatedList;
        });
    };

    return (
        <React.Fragment>
            <NotificationContainer />
            {isLoading ? (
                <div className="bg-light opacity-0.25">
                    <div className="d-flex justify-content-center m-5">
                        <Spinner className="mt-5 mb-5" animation="border" />
                    </div>
                </div>
            ) : (
                <>
                    <Card>
                        <Card.Body>
                            <h4 className="text-bold mb-4">{'Staff Salary'}</h4>
                            <FormLayout
                                dynamicForm={formContain}
                                handleSubmit={onFormSubmit}
                                optionListState={optionListState}
                                setState={setState}
                                onChangeCallBack={{
                                    handleDate: handleDate,
                                    handleDepartment: handleDepartment,
                                    handleBranch: handleBranch,
                                }}
                                state={state}
                                noOfColumns={1}
                            />
                            <Table bordered responsive className="mt-3">
                                <thead>
                                    <tr>
                                        <th style={{ whiteSpace: 'nowrap' }}>
                                            S.No
                                            <Form.Check
                                                type="checkbox"
                                                name="selectAll"
                                                onChange={(e) => onHandleAllRows(e.target.checked, 'isChecked')}
                                                checked={(parentList || []).every((item) => item?.isChecked) || false}
                                                style={{ marginLeft: '10px', display: 'inline' }}
                                            />
                                        </th>
                                        <th>Employee&nbsp;Name</th>
                                        <th style={{ minWidth: '220px', textAlign: 'left' }}>Staff&nbsp;Attendance</th>
                                        <th>Staff&nbsp;Advance</th>
                                        <th>Gross&nbsp;Salary</th>
                                        <th>Total&nbsp;Deduction</th>
                                        <th>Total&nbsp;Allowance</th>
                                        <th style={{ minWidth: '220px', textAlign: 'left' }}>Net&nbsp;Salary</th>
                                        <th>Status</th>
                                        <th>Payslip</th>
                                    </tr>
                                </thead>
                                <tbody>
                                    {parentList && parentList.length > 0 ? (
                                        parentList.map((person, index) => {
                                            const Inc =
                                                person?.deductionDetails?.allowance?.reduce((acc, curr) => {
                                                    const v = Object.values(curr)[0];
                                                    return Number(v.isIncrement) === 0 ? acc + Number(v.deductionAmount || 0) : acc;
                                                }, 0) || 0;
                                            const Incr =
                                                person?.deductionDetails?.allowance?.reduce((acc, curr) => {
                                                    const v = Object.values(curr)[0];
                                                    return Number(v.isIncrement) === 1 ? acc + Number(v.deductionAmount || 0) : acc;
                                                }, 0) || 0

                                            const finalTotal = (person?.netPayableSalary || 0) - Inc - Incr + person?.deductionDetails?.totalDeduction;
                                            return (
                                                <tr
                                                    key={`${person.employeeId}-${person.attedancePeopleId || index}`}
                                                    style={{
                                                        backgroundColor: !person.isChecked ? '#e9ecef' : '#fff',
                                                        cursor: !person.isChecked ? 'not-allowed' : 'auto',
                                                    }}>
                                                    <td>
                                                        {index + 1}
                                                        <Form.Check
                                                            type="checkbox"
                                                            name="selectAll"
                                                            onChange={(e) =>
                                                                onHandleEachRow(e.target.checked, index, 'isChecked')
                                                            }
                                                            checked={person.isChecked || false}
                                                            style={{
                                                                marginLeft: '10px',
                                                                display: 'inline',
                                                            }}
                                                        />
                                                    </td>
                                                    {/* staff profile */}
                                                    <td>
                                                        <div
                                                            className="inbox-item-img"
                                                            style={{ display: 'flex', alignItems: 'center' }}>
                                                            <img
                                                                src={
                                                                    person?.staffProfile
                                                                        ? `${baseURL}${person.staffProfile}`
                                                                        : noProfile
                                                                }
                                                                alt="staffProfile"
                                                                className="rounded-circle"
                                                                crossOrigin="anonymous"
                                                                onError={(e) => {
                                                                    e.target.onerror = null;
                                                                    e.target.src = noProfile;
                                                                }}
                                                                style={{
                                                                    width: '40px',
                                                                    height: '40px',
                                                                    objectFit: 'cover',
                                                                    marginRight: '10px',
                                                                }}
                                                            />
                                                            <div>
                                                                <div style={{ fontSize: '15px', fontWeight: '600' }}>
                                                                    {person?.staffName}
                                                                </div>
                                                                <div style={{ fontSize: '12px', color: '#888' }}>
                                                                    {person?.staffCode}
                                                                </div>
                                                            </div>
                                                        </div>
                                                    </td>
                                                    <td className="d-flex flex-column align-items-end" style={{ padding: '8px 12px' }}>
                                                        <div style={{ fontSize: 13, lineHeight: 1.8, width: '100%' }}>
                                                            <div style={{ display: 'flex', justifyContent: 'space-between', color: "#0582b4ff", fontWeight: "bold" }}>
                                                                <span>Office Days:</span>
                                                                <span>{(person?.totalOfficeDays || 0)}</span>
                                                            </div>
                                                            <div style={{ display: 'flex', justifyContent: 'space-between', color: '#28a645ff', fontWeight: "bold" }}>
                                                                <span>Total Present:</span>
                                                                <span>{(person?.presentPlusHalfdays || 0)}</span>
                                                            </div>
                                                            <div style={{ display: 'flex', justifyContent: 'space-between', color: '#c92e3eff', fontWeight: "bold" }}>
                                                                <span>Total Absent:</span>
                                                                <span>{(person?.absentDays || 0)}</span>
                                                            </div>
                                                            <div style={{ display: 'flex', justifyContent: 'space-between', color: 'rgba(179, 36, 112, 1)', fontWeight: "bold" }}>
                                                                <span>Holidays: </span>
                                                                <span>{(person?.totalHolidayAndSunday || 0)}</span>
                                                            </div>
                                                            <div style={{ display: 'flex', justifyContent: 'space-between', color: "#4d5359ff", fontWeight: "bold" }}>
                                                                <span>Att. Not Marked:</span>
                                                                <span>{(person?.attendanceNotEntryCount || 0)}</span>
                                                            </div>
                                                        </div>
                                                        <div
                                                            style={{
                                                                borderTop: '1px dashed #ccc',
                                                                marginTop: 10,
                                                                paddingTop: 6,
                                                                fontWeight: 'bold',
                                                                fontSize: 15,
                                                                textAlign: 'right',
                                                                width: '100%'
                                                            }}
                                                        >
                                                            <div style={{ display: 'flex', justifyContent: 'space-between', color: "#000000ff", fontWeight: "bold" }}>
                                                                <span>Total Days:</span>
                                                                <span>{(person?.totalDays || 0)}</span>
                                                            </div>
                                                        </div>
                                                    </td>

                                                    <td>
                                                        {person?.totalAdvanceAmount ? (
                                                            <ul
                                                                style={{
                                                                    margin: 0,
                                                                    padding: 0,
                                                                    listStyleType: 'none',
                                                                }}>
                                                                <li style={{ display: 'flex' }}>
                                                                    <span
                                                                        style={{
                                                                            display: 'inline-block',
                                                                            width: '40px',
                                                                        }}>
                                                                        Adv:
                                                                    </span>
                                                                    <span style={{ color: '#000' }}>
                                                                        {numberWithCommas(
                                                                            person?.totalAdvanceAmount || 0
                                                                        )}
                                                                    </span>
                                                                </li>
                                                                <li style={{ display: 'flex' }}>
                                                                    <span
                                                                        style={{
                                                                            display: 'inline-block',
                                                                            width: '40px',
                                                                        }}>
                                                                        Paid:
                                                                    </span>
                                                                    <span style={{ color: 'green' }}>
                                                                        {numberWithCommas(
                                                                            person?.totalPaidAdvanceAmount || 0
                                                                        )}
                                                                    </span>
                                                                </li>
                                                                <li style={{ display: 'flex' }}>
                                                                    <span
                                                                        style={{
                                                                            display: 'inline-block',
                                                                            width: '40px',
                                                                        }}>
                                                                        Bal:
                                                                    </span>
                                                                    <span style={{ color: 'red' }}>
                                                                        {numberWithCommas(
                                                                            person?.balanceAdvanceAmount || 0
                                                                        )}
                                                                    </span>
                                                                </li>
                                                            </ul>
                                                        ) : (
                                                            <span>No Advance</span>
                                                        )}
                                                    </td>
                                                    <td>
                                                        <span>{`${numberWithCommas(person?.monthlySalary || 0)}`}</span>
                                                    </td>
                                                    {/* Staff Deduction */}
                                                    <td>
                                                        {person.deductionDetails?.deduction?.length > 0 ? (
                                                            <ul
                                                                style={{
                                                                    margin: 0,
                                                                    padding: 0,
                                                                    listStyleType: 'none',
                                                                }}>
                                                                {(person.deductionDetails.deduction || []).map(
                                                                    (deduct, dIndex) => {
                                                                        const key = Object.keys(deduct)[0];
                                                                        const value = deduct[key];
                                                                        const isPercent =
                                                                            Number(value.isPercentage) === 1;

                                                                        return (
                                                                            <li
                                                                                key={dIndex}
                                                                                style={{
                                                                                    display: 'flex',
                                                                                    alignItems: 'center',
                                                                                    whiteSpace: 'nowrap',
                                                                                    marginBottom: 4,
                                                                                }}>
                                                                                <span
                                                                                    style={{
                                                                                        minWidth: 140,
                                                                                        fontWeight: 500,
                                                                                        overflow: 'hidden',
                                                                                        textOverflow: 'ellipsis',
                                                                                    }}>
                                                                                    {key}
                                                                                </span>

                                                                                <span style={{ color: '#000' }}>
                                                                                    {isPercent ? '' : '₹'}
                                                                                </span>

                                                                                <input
                                                                                    type="number"
                                                                                    value={value.deductionValue}
                                                                                    style={{
                                                                                        width: 70,
                                                                                        border: 'none',
                                                                                        borderBottom: '1px solid black',
                                                                                        outline: 'none',
                                                                                        background: 'transparent',
                                                                                        fontSize: '14px',
                                                                                        padding: '2px 4px',
                                                                                    }}
                                                                                    onChange={(e) =>
                                                                                        handleDeductionChange(
                                                                                            index,
                                                                                            dIndex,
                                                                                            'deductionValue',
                                                                                            e.target.value
                                                                                        )
                                                                                    }
                                                                                />

                                                                                <span
                                                                                    style={{
                                                                                        color: '#000',
                                                                                        minWidth: 30,
                                                                                    }}>
                                                                                    {isPercent ? '%' : ''}
                                                                                </span>

                                                                                <span
                                                                                    style={{
                                                                                        color: 'red',
                                                                                        fontWeight: 600,
                                                                                        marginLeft: 'auto',
                                                                                    }}>
                                                                                    ₹{' '}
                                                                                    {numberWithCommas(
                                                                                        value?.deductionAmount || 0
                                                                                    )}
                                                                                </span>
                                                                            </li>
                                                                        );
                                                                    }
                                                                )}
                                                                <li
                                                                    style={{
                                                                        display: 'flex',
                                                                        justifyContent: 'space-between',
                                                                        alignItems: 'center',
                                                                        marginTop: '4px',
                                                                        borderTop: '1px solid #ccc',
                                                                        paddingTop: '4px',
                                                                    }}>
                                                                    <span
                                                                        style={{
                                                                            minWidth: '140px',
                                                                            fontWeight: 'bold',
                                                                        }}>
                                                                        Total
                                                                    </span>
                                                                    <span style={{ color: 'red', fontWeight: 600 }}>
                                                                        ₹{' '}
                                                                        {numberWithCommas(
                                                                            person?.deductionDetails?.totalDeduction || 0
                                                                        )}
                                                                    </span>
                                                                </li>
                                                            </ul>
                                                        ) : (
                                                            <span style={{ color: '#999' }}>No Deduction</span>
                                                        )}
                                                    </td>

                                                    {/* Staff Allowance */}
                                                    <td key={index}>
                                                        <div style={{ display: 'flex', gap: 12 }}>
                                                            {/* Left Column - Including */}
                                                            <ul style={{ flex: 1, margin: 0, padding: 0, listStyleType: 'none' }}>
                                                                <li style={{ fontWeight: 'bold', marginBottom: 4 }}>Including</li>
                                                                {(() => {
                                                                    const includingItems = person.deductionDetails?.allowance?.filter(
                                                                        item => Number(Object.values(item)[0].isIncrement) === 0
                                                                    );

                                                                    if (!includingItems || includingItems.length === 0) {
                                                                        return (
                                                                            <li style={{ fontStyle: 'italic', color: 'gray', padding: '4px 0' }}>
                                                                                Including&nbsp;Not&nbsp;Allocated
                                                                            </li>
                                                                        );
                                                                    }

                                                                    return includingItems.map((deduct, aIndex) => {
                                                                        const key = Object.keys(deduct)[0];
                                                                        const value = deduct[key];
                                                                        const isPercent = Number(value.isPercentage) === 1;

                                                                        return (
                                                                            <li
                                                                                key={`inc-${aIndex}`}
                                                                                style={{
                                                                                    display: 'flex',
                                                                                    alignItems: 'center',
                                                                                    whiteSpace: 'nowrap',
                                                                                    marginBottom: 4,
                                                                                    padding: '2px 4px',
                                                                                    borderRadius: 4,
                                                                                }}
                                                                            >
                                                                                <span style={{ minWidth: 140 }}>{key}</span>
                                                                                <span style={{ color: '#000', marginLeft: 6 }}>{isPercent ? '' : '₹'}</span>
                                                                                <input
                                                                                    type="number"
                                                                                    value={value.deductionValue}
                                                                                    style={{
                                                                                        width: 70,
                                                                                        border: 'none',
                                                                                        borderBottom: '1px solid black',
                                                                                        outline: 'none',
                                                                                        background: 'transparent',
                                                                                        fontSize: '14px',
                                                                                        padding: '2px 4px',
                                                                                    }}
                                                                                    onChange={(e) => handleAllowanceChange(index, key, 'deductionValue', e.target.value)}
                                                                                />
                                                                                <span style={{ color: '#000', minWidth: 30 }}>{isPercent ? '%' : ''}</span>
                                                                                <span style={{ color: 'green', fontWeight: 600, marginLeft: 'auto' }}>
                                                                                    ₹ {numberWithCommas(value?.deductionAmount || 0)}
                                                                                </span>
                                                                            </li>
                                                                        );
                                                                    });
                                                                })()}
                                                            </ul>

                                                            {/* Right Column - Increment */}
                                                            <ul style={{ flex: 1, margin: 0, padding: 0, listStyleType: 'none' }}>
                                                                <li style={{ fontWeight: 'bold', marginBottom: 4 }}>Increment</li>
                                                                {(() => {
                                                                    const incrementItems = person.deductionDetails?.allowance?.filter(
                                                                        item => Number(Object.values(item)[0].isIncrement) === 1
                                                                    );

                                                                    if (!incrementItems || incrementItems.length === 0) {
                                                                        return (
                                                                            <li style={{ fontStyle: 'italic', color: 'gray', padding: '4px 0' }}>
                                                                                Increment&nbsp;Not&nbsp;Allocated
                                                                            </li>
                                                                        );
                                                                    }

                                                                    return incrementItems.map((deduct, aIndex) => {
                                                                        const key = Object.keys(deduct)[0];
                                                                        const value = deduct[key];
                                                                        const isPercent = Number(value.isPercentage) === 1;

                                                                        return (
                                                                            <li
                                                                                key={`incmt-${aIndex}`}
                                                                                style={{
                                                                                    display: 'flex',
                                                                                    alignItems: 'center',
                                                                                    whiteSpace: 'nowrap',
                                                                                    marginBottom: 4,
                                                                                    backgroundColor: '#e6ffe6',
                                                                                    fontWeight: 600,
                                                                                    padding: '2px 4px',
                                                                                    borderRadius: 4,
                                                                                }}
                                                                            >
                                                                                <span style={{ minWidth: 140 }}>{key}</span>
                                                                                <span style={{ color: '#000', marginLeft: 6 }}>{isPercent ? '' : '₹'}</span>
                                                                                <input
                                                                                    type="number"
                                                                                    value={value.deductionValue}
                                                                                    style={{
                                                                                        width: 70,
                                                                                        border: 'none',
                                                                                        borderBottom: '1px solid black',
                                                                                        outline: 'none',
                                                                                        background: 'transparent',
                                                                                        fontSize: '14px',
                                                                                        padding: '2px 4px',
                                                                                    }}
                                                                                    onChange={(e) => handleAllowanceChange(index, key, 'deductionValue', e.target.value)}
                                                                                />
                                                                                <span style={{ color: '#000', minWidth: 30 }}>{isPercent ? '%' : ''}</span>
                                                                                <span style={{ color: 'green', fontWeight: 600, marginLeft: 'auto' }}>
                                                                                    ₹ {numberWithCommas(value?.deductionAmount || 0)}
                                                                                </span>
                                                                            </li>
                                                                        );
                                                                    });
                                                                })()}
                                                            </ul>
                                                        </div>

                                                        {/* Total Including + Increment (same line) */}
                                                        <div
                                                            style={{
                                                                marginTop: 6,
                                                                paddingTop: 6,
                                                                borderTop: '2px solid #aaa',
                                                                display: 'flex',
                                                                flexDirection: 'column',
                                                                gap: 6,
                                                                fontWeight: 'bold',
                                                            }}
                                                        >
                                                            <div style={{ display: 'flex', justifyContent: 'space-between' }}>
                                                                <span>Total Including: </span>
                                                                <span>
                                                                    ₹{' '}
                                                                    {numberWithCommas(
                                                                        person?.deductionDetails?.allowance?.reduce((acc, curr) => {
                                                                            const v = Object.values(curr)[0];
                                                                            return Number(v.isIncrement) === 0 ? acc + Number(v.deductionAmount || 0) : acc;
                                                                        }, 0) || 0
                                                                    )}
                                                                </span>
                                                            </div>

                                                            <div style={{ display: 'flex', justifyContent: 'space-between' }}>
                                                                <span>Total Increment:</span>
                                                                <span>
                                                                    ₹{' '}
                                                                    {numberWithCommas(
                                                                        person?.deductionDetails?.allowance?.reduce((acc, curr) => {
                                                                            const v = Object.values(curr)[0];
                                                                            return Number(v.isIncrement) === 1 ? acc + Number(v.deductionAmount || 0) : acc;
                                                                        }, 0) || 0
                                                                    )}
                                                                </span>
                                                            </div>

                                                            <div style={{ display: 'flex', justifyContent: 'space-between', borderTop: '1px dashed #ccc', paddingTop: 6 }}>


                                                                <span>Final Total:</span>
                                                                <span style={{ color: 'green' }}>
                                                                    ₹{' '}
                                                                    {numberWithCommas(
                                                                        person.deductionDetails?.allowance?.reduce((acc, curr) => {
                                                                            const v = Object.values(curr)[0];
                                                                            return acc + Number(v.deductionAmount || 0);
                                                                        }, 0)
                                                                        || 0
                                                                    )}
                                                                </span>
                                                            </div>
                                                        </div>
                                                        <div style={{ marginTop: "20px", marginBottom: "10px" }}>
                                                            <span style={{ fontWeight: "bold" }}>Note:</span> Earning amount is expected to be <b>₹0</b>, but currently shows: <span style={{ color: finalTotal == 0 ? "green" : "red", fontWeight: "bold" }}>₹ {numberWithCommas(finalTotal)}</span>
                                                        </div>
                                                    </td>

                                                    <td className="d-flex flex-column align-items-end" style={{ padding: '8px 12px' }}>
                                                        <div style={{ fontSize: 13, lineHeight: 1.8, width: '100%' }}>
                                                            <div style={{ display: 'flex', justifyContent: 'space-between' }}>
                                                                <span>Present Salary:</span>
                                                                <span>₹ {numberWithCommas(person?.presentAndHalfDaySalary || 0)}</span>
                                                            </div>
                                                            <div style={{ display: 'flex', justifyContent: 'space-between', color: '#28a745' /* green */ }}>
                                                                <span>Total Increment:</span>
                                                                <span>₹ {numberWithCommas(person?.deductionDetails?.totalIncrementAllowance || 0)}</span>
                                                            </div>
                                                            <div style={{ display: 'flex', justifyContent: 'space-between', color: '#dc3545' /* red */ }}>
                                                                <span>Total Deduction:</span>
                                                                <span>₹ {numberWithCommas(person?.deductionDetails?.totalDeduction || 0)}</span>
                                                            </div>
                                                        </div>

                                                        <div
                                                            style={{
                                                                borderTop: '1px dashed #ccc',
                                                                marginTop: 10,
                                                                paddingTop: 6,
                                                                fontWeight: 'bold',
                                                                fontSize: 15,
                                                                textAlign: 'right',
                                                                width: '100%'
                                                            }}
                                                        >
                                                            <div style={{ display: 'flex', justifyContent: 'space-between' }}>
                                                                <span>Net Pay:</span>
                                                                <span>₹ {numberWithCommas(person?.netPayableSalary || 0)}</span>
                                                            </div>
                                                        </div>
                                                    </td>

                                                    <td>
                                                        <span
                                                            style={{
                                                                color: person.status ? 'green' : 'red',
                                                                fontWeight: '500',
                                                            }}>
                                                            {person.status ? 'PAID' : 'UNPAID'}
                                                        </span>
                                                    </td>
                                                    <td>
                                                        {
                                                            person.status ?
                                                                <span className="text-success  me-2 cursor-pointer"
                                                                    onClick={() => navigate('/pay-slip-report', { state: person })}>
                                                                    <i className={'fe-printer'} style={{ fontSize: '19px' }}></i>
                                                                </span> : <strong>No&nbsp;Payslip</strong>
                                                        }
                                                    </td>
                                                </tr>
                                            );
                                        })
                                    ) : (
                                        <tr>
                                            <td colSpan="13" className="text-center">
                                                No data available
                                            </td>
                                        </tr>
                                    )}
                                </tbody>
                            </Table>

                            <div className='d-flex justify-content-end mt-3'>
                                {roleIdforRole == 1 ? <Button
                                    variant={'primary'}
                                    className="waves-effect waves-light me-1"
                                    type="button"
                                    onClick={onFormSubmit}>
                                    {`Submit`}
                                </Button> : ''}
                            </div>
                        </Card.Body>
                    </Card>
                </>
            )}
        </React.Fragment>
    );
}

export default Index;
